effect.shader:
float gmHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float gmNoise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(gmHash(i),gmHash(i+vec2(1,0)),f.x),mix(gmHash(i+vec2(0,1)),gmHash(i+vec2(1)),f.x),f.y);}
void main(){
vec2 uv=acScreenNorm; vec2 px=max(acScreenSize,vec2(1.0)); vec4 src=texture2DCv(inputImg.texture,uv);
vec2 q=uv-emitter; q.x*=px.x/px.y; float t=acTime*speed+evolution;
float field=0.0; vec3 particles=vec3(0.0);
for(int layer=0;layer<4;layer++){
float z=float(layer)+1.0; float scale=(px.y/max(sizePx,1.0))*(0.18+z*0.08);
vec2 p=q*scale; p.y+=t*(1.4+z*0.37); p.x+=sin(p.y*0.73+t+z)*turbulence;
vec2 cell=floor(p), local=fract(p)-0.5; float rnd=gmHash(cell+vec2(z,evolution*0.13));
local.x+=(rnd-0.5)*0.75; local.y+=(gmHash(cell+7.3)-0.5)*0.55;
float shape=1.0-smoothstep(0.08,0.5,length(local));
float emit=exp(-abs(q.x)/max(spread,0.001))*(1.0-smoothstep(-0.25,0.75,q.y));
float spawnMask=step(1.0-density,rnd)*emit;
if(particleMode==1) shape*=(1.0-smoothstep(0.05,0.55,abs(local.x)))*(1.0-smoothstep(-0.45,0.55,local.y));
if(particleMode==2) shape=(1.0-smoothstep(0.05,0.62,length(local)))*0.55;
if(particleMode==3) shape=1.0-smoothstep(0.04,0.22,length(local));
float a=shape*spawnMask/(0.6+z*0.45); field+=a; particles+=mix(colorA.rgb,colorB.rgb,rnd)*a;
}
field=clamp(field*intensity,0.0,1.0); particles*=intensity;
vec3 added=1.0-(1.0-src.rgb)*(1.0-clamp(particles,0.0,1.0));
if(particleMode==2) added=mix(src.rgb,mix(src.rgb,colorB.rgb,0.65),field);
vec3 rgb=mix(src.rgb,added,mixAmount); float a=src.a+field*mixAmount*(1.0-src.a);
gl_FragColor=vec4(rgb,a);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
